import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/mobs/commands.md","filePath":"en/modules/mobs/commands.md","lastUpdated":0}`),a={name:`en/modules/mobs/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-permissions" tabindex="-1">Commands &amp; Permissions <a class="header-anchor" href="#commands-permissions" aria-label="Permalink to “Commands &amp; Permissions”">​</a></h1><p>The root command is <code>/emakimobs</code>, with <code>/emobs</code> as an alias. Running it without a subcommand prints the usage hint; an unknown subcommand does the same</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><p>Every subcommand&#39;s <code>mob_id</code> argument is <strong>case-sensitive</strong> (matched exactly against definition ids; an unknown id reports an unknown mob)</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/emakimobs spawn &lt;mob_id&gt; [player]</code></td><td><code>emakimobs.spawn</code></td><td>Spawn the specified mob at the target player&#39;s location. When <code>player</code> is omitted, spawns at the command sender&#39;s location; from the console, <code>player</code> is required. <code>player</code> is matched exactly by name (<code>Bukkit.getPlayerExact</code>); a missing or offline player reports no target</td></tr><tr><td><code>/emakimobs reload</code></td><td><code>emakimobs.reload</code></td><td>Reload all mob definitions, loot tables, spawn rules, and target selectors without restarting the server. When the precheck finds an ERROR the commit is rejected and the previous content is restored; the reported count is then the number of definitions still in effect</td></tr><tr><td><code>/emakimobs list [page]</code></td><td><code>emakimobs.list</code></td><td>Paginate through every registered mob definition (10 per page, sorted by id), with a header line giving total pages, total count and the current page. <code>page</code> defaults to 1; a non-positive integer reports an invalid page and an out-of-range page reports the range</td></tr><tr><td><code>/emakimobs info &lt;mob_id&gt;</code></td><td><code>emakimobs.info</code></td><td>Show the mob&#39;s vanilla type, <code>components</code> key count, <code>ea_attributes</code> key count, configured trigger list, and whether a matching <code>loot_tables/&lt;mob_id&gt;.yml</code> exists</td></tr><tr><td><code>/emakimobs kill &lt;mob_id&gt; [radius]</code></td><td><code>emakimobs.admin</code></td><td>Remove managed mobs of that id. With <code>radius</code>, only targets within that radius of the executor are removed, so the radius form is player-only; <code>radius</code> must be a finite value ≥ 0</td></tr><tr><td><code>/emakimobs kill all [radius]</code></td><td><code>emakimobs.admin</code></td><td>Remove <strong>all</strong> managed mobs regardless of id. Without <code>radius</code> it scans every world; with <code>radius</code> only targets within that range are removed (also player-only)</td></tr><tr><td><code>/emakimobs count [mob_id]</code></td><td><code>emakimobs.count</code></td><td>Count managed mobs; with <code>mob_id</code> omitted it counts all of them (reported as <code>*</code> in the message). Only entities whose PDC id is still in the currently loaded set are counted; an unregistered <code>mob_id</code> reports an unknown mob</td></tr><tr><td><code>/emakimobs find &lt;mob_id&gt; [radius]</code></td><td><code>emakimobs.count</code></td><td>Find managed mobs and list them sorted by distance (up to 20 entries plus a truncation line). <code>radius</code> omitted means unlimited range; player-only. Each entry shows id, UUID and health on hover, and clicking runs <code>/emakimobs tp &lt;uuid&gt;</code></td></tr><tr><td><code>/emakimobs tp &lt;uuid&gt;</code></td><td><code>emakimobs.admin</code></td><td>Teleport to the managed mob with that UUID; a missing or unmanaged target is rejected. Usually triggered from a <code>find</code> list entry</td></tr><tr><td><code>/emakimobs edit [id]</code></td><td><code>emakimobs.edit</code></td><td>Open the in-game definition editor: omitting <code>id</code> opens the file browser (paging, create, delete), passing <code>id</code> opens that mob definition for field-by-field editing</td></tr><tr><td><code>/emakimobs help</code></td><td><code>emakimobs.use</code></td><td>Print the command help list</td></tr><tr><td><code>/emakimobs debug ...</code></td><td><code>emakimobs.debug</code></td><td>Forwards to the module&#39;s debug subcommand (CoreLib debug command, module filter <code>mobs</code>); reports when the debug handler is unavailable</td></tr></tbody></table><p><code>count</code>, <code>kill</code> and <code>find</code> scan entities through the dispatcher and deliver the result back to the sender (the player&#39;s own thread, or the global thread for the console). Once shutdown has started, no result is delivered. Candidates are scanned with <code>world.getEntities()</code> across every world plus the PDC <code>isManaged</code> marker, so mobs in reloaded chunks are neither undercounted nor missed</p><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission nodes”">​</a></h2><p><code>emakimobs.use</code> gates the whole command: without it the command is not usable (<code>canUse</code> fails) and no subcommand runs. The remaining nodes are checked per subcommand, each reporting a missing-permission message</p><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakimobs.use</code></td><td><code>true</code> (all players)</td><td>Base permission to use the <code>/emakimobs</code> command</td></tr><tr><td><code>emakimobs.spawn</code></td><td><code>op</code></td><td>Manually spawn custom mobs</td></tr><tr><td><code>emakimobs.reload</code></td><td><code>op</code></td><td>Reload configuration files</td></tr><tr><td><code>emakimobs.list</code></td><td><code>op</code></td><td>List registered mob definitions</td></tr><tr><td><code>emakimobs.info</code></td><td><code>op</code></td><td>Inspect a single mob definition</td></tr><tr><td><code>emakimobs.count</code></td><td><code>op</code></td><td>Count managed mobs; also gates <code>find</code></td></tr><tr><td><code>emakimobs.edit</code></td><td><code>op</code></td><td>Open the in-game definition editor</td></tr><tr><td><code>emakimobs.debug</code></td><td><code>op</code></td><td>Module debug subcommand</td></tr><tr><td><code>emakimobs.admin</code></td><td><code>op</code></td><td>Administration; used by <code>kill</code> (including <code>kill all</code>) and <code>tp</code></td></tr></tbody></table><p>Tab completion filters subcommands by the sender&#39;s permissions and completes <code>mob_id</code> for <code>spawn</code> / <code>info</code> / <code>kill</code> / <code>count</code> / <code>find</code>, online player names for <code>spawn</code>, the radius for <code>find</code> / <code>kill</code>, and the page number for <code>list</code></p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Spawn an elite zombie at your own location</span></span>
<span class="line"><span>/emakimobs spawn elite_zombie</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Spawn a bone lord at player Steve&#39;s location</span></span>
<span class="line"><span>/emakimobs spawn bone_lord Steve</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Paginate through the registered mob definitions</span></span>
<span class="line"><span>/emakimobs list 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Inspect the bone lord definition</span></span>
<span class="line"><span>/emakimobs info bone_lord</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Count living elite zombies</span></span>
<span class="line"><span>/emakimobs count elite_zombie</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Remove elite zombies within 32 blocks</span></span>
<span class="line"><span>/emakimobs kill elite_zombie 32</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Remove all managed mobs within 64 blocks</span></span>
<span class="line"><span>/emakimobs kill all 64</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Remove every managed mob in every world</span></span>
<span class="line"><span>/emakimobs kill all</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Find elite zombies nearby and click to teleport</span></span>
<span class="line"><span>/emakimobs find elite_zombie 48</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Reload all config files</span></span>
<span class="line"><span>/emakimobs reload</span></span></code></pre></div><div class="caution custom-block"><p class="custom-block-title custom-block-title-default">CAUTION</p><p>The <code>spawn</code> command places the mob at the exact coordinates of the target player. Test in open areas to prevent mobs from becoming stuck inside blocks</p></div>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};